import { tags } from "typia";

/**
 * Cart population metrics for analytics.
 *
 * Provides basic counts related to cart creation and progression towards
 * checkout within a cohort or overall dataset.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCartCounts = {
  /**
   * Total number of distinct carts created within the analytics window for
   * this cohort or overall dataset.
   */
  totalCarts: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of carts that remained active (not checked out or deleted) by the
   * end of the analytics window.
   */
  activeCarts: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of carts that reached the checkout stage at least once within the
   * analytics window.
   */
  cartsReachedCheckout: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Average number of cart items per cart, computed over all carts in the
   * cohort or overall dataset.
   */
  averageItemsPerCart: number & tags.Minimum<0>;
};
